<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Haven Suites - Payment Claims</title><style>body{font:15px Arial;margin:25px;color:#243253}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:10px;vertical-align:top}th{background:#243253;color:white}pre{white-space:pre-wrap;word-break:break-word}button{padding:8px;cursor:pointer}</style></head><body><h2>Quotation payment claims (manual review)</h2><p>Review against actual M-Pesa transactions. Marking reviewed does NOT post a guest payment or issue a receipt.</p><table><tr><th>Reservation</th><th>Claim</th><th>Message</th><th>Status</th><th>Action</th></tr><?php foreach($claims as $c): ?><tr><td><?= esc($c['reservation_id']) ?></td><td>KES <?= number_format((float)$c['amount'],2) ?><br><?= esc($c['mpesa_code']) ?><br><?= esc($c['submitted_at']) ?></td><td><pre><?= esc($c['mpesa_message']) ?></pre></td><td><?= esc($c['status']) ?></td><td><?php if($c['status']==='pending'): ?><?php if (haven_can_access(esc(site_url('quotations/payment-claims/'.$c['id'].'/review'),'attr'), 'POST')): ?><form method="post" action="<?= esc(site_url('quotations/payment-claims/'.$c['id'].'/review'),'attr') ?>"><?= csrf_field() ?><button name="decision" value="reviewed">Mark reviewed</button> <button name="decision" value="rejected">Reject</button></form><?php endif; ?><?php endif; ?></td></tr><?php endforeach; ?></table></body></html>
